namespace Qlcheck.Languages.CSharp;

// Code a tool wrote: by file name (`.g.cs`, `.g.i.cs`, `.Designer.cs`, `.generated.cs`) or by an
// `<auto-generated` comment in its first lines. Coverage and duplicate detection skip it.
internal static class GeneratedFiles
{
    private const int HeaderLines = 5;

    private const string Marker = "<auto-generated";

    private static readonly string[] Suffixes = [".g.cs", ".g.i.cs", ".Designer.cs", ".generated.cs"];

    public static bool IsGenerated(string path, string text) =>
        Suffixes.Any(suffix => path.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
        || text.Split('\n', HeaderLines + 1).Take(HeaderLines).Any(line => line.Contains(Marker, StringComparison.OrdinalIgnoreCase));
}
